parameters.jsCode:
const raw = $input.first().json.content[0].text;
let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch(e) {
  parsed = { energy_level: 5, mood_check: true, notes_good: raw, notes_tomorrow: '', extra_todos: [], summary: 'Sprachnotiz verarbeitet' };
}
return [{ json: parsed }];

